    """Shared operations for file handlers."""

    @property
    def spacecraft_name(self):
        """Return spacecraft name."""
        return platform_name_translate.get(
            self.nc.attrs["platform"], self.nc.attrs["platform"])

    @property
    def sensor_name(self):
        """Return instrument name."""
        return self.nc.attrs["data_source"].lower()

    @property
    def ssp_lon(self):
        """Return longitude at subsatellite point."""
        try:
            return float(self.nc["mtg_geos_projection"].attrs["longitude_of_projection_origin"])
        except (KeyError, AttributeError):
            logger.warning(f"ssp_lon could not be obtained from file content, using default value "
                           f"of {SSP_DEFAULT} degrees east instead")
            return SSP_DEFAULT

    def _get_global_attributes(self, product_type="pixel"):
        """Create a dictionary of global attributes to be added to all datasets.

        Returns:
            dict: A dictionary of global attributes.
                filename: name of the product file
                spacecraft_name: name of the spacecraft
                ssp_lon: longitude of subsatellite point
                sensor: name of sensor
                platform_name: name of the platform
            Only for AMVs product:
                channel: channel at which the AMVs have been retrieved


        """
        attributes = {
            "filename": self.filename,
            "spacecraft_name": platform_name_translate.get(self.spacecraft_name, self.spacecraft_name),
            "ssp_lon": self.ssp_lon,
            "sensor": self.sensor_name,
            "platform_name": platform_name_translate.get(self.spacecraft_name, self.spacecraft_name)
        }

        if product_type=="amv":
            attributes["channel"] = self.filename_info["channel"]

        return attributes

    def _set_attributes(self, variable, dataset_info, product_type="pixel"):
        """Set dataset attributes."""
        if product_type in ["pixel", "segmented"]:
            if product_type == "pixel":
                xdim, ydim = "number_of_columns", "number_of_rows"
            elif product_type == "segmented":
                xdim, ydim = "number_of_FoR_cols", "number_of_FoR_rows"

            if dataset_info["nc_key"] not in ["product_quality",
                                              "product_completeness",
                                              "product_timeliness"]:
                variable = variable.swap_dims({ydim: "y", xdim: "x"})

        variable.attrs.setdefault("units", None)
        if "unit" in variable.attrs:
            # Need to convert this attribute to the expected satpy entry
            variable.attrs.update({"units": variable.attrs["unit"]})
            del variable.attrs["unit"]

        variable.attrs.update(dataset_info)
        variable.attrs.update(self._get_global_attributes(product_type=product_type))

        import_enum_information = dataset_info.get("import_enum_information", False)
        if import_enum_information:
            variable = self._add_flag_values_and_meanings(self.filename, dataset_info["nc_key"], variable)

        if variable.attrs["units"] == "none":
            variable.attrs.update({"units": None})

        return variable

    @staticmethod
    def _add_flag_values_and_meanings(filename, key, variable):
        """Build flag values and meaning from enum datatype."""
        nc_dataset = netCDF4.Dataset(filename, "r")
        # This currently assumes a flat netCDF file
        data_type = nc_dataset.variables[key].datatype
        if hasattr(data_type, "enum_dict"):
            enum = data_type.enum_dict
            flag_values = []
            flag_meanings = []
            for meaning, value in enum.items():
                flag_values.append(value)
                flag_meanings.append(meaning)

            variable.attrs["flag_values"] = flag_values
            variable.attrs["flag_meanings"] = flag_meanings
            nc_dataset.close()

        return variable

    def _slice_dataset(self, variable, dataset_info, dimensions):
        """Slice data if dimension layers have been provided in yaml-file."""
        slice_dict = {dim: dataset_info[dim_id] for (dim, dim_id) in dimensions.items()
                      if dim_id in dataset_info.keys() and dim in variable.dims}
        for dim, dim_ind in slice_dict.items():
            logger.debug(f"Extracting {dimensions[dim]}-index {dim_ind} from dimension {dim!r}.")
        variable = variable.sel(slice_dict)

        return variable

    @staticmethod
    def _mask_data(variable, fill_value):
        """Set fill_values, as defined in yaml-file, to NaN.

        Set data points in variable to NaN if they are equal to fill_value
        or any of the values in fill_value if fill_value is a list.
        """
        if not isinstance(fill_value, list):
            fill_value = [fill_value]

        for val in fill_value:
            variable = variable.where(variable != val).astype("float32")

        return variable

    def __del__(self):
        """Close the NetCDF file that may still be open."""
        with suppress(AttributeError, OSError):
            self.nc.close()


